per_case_results.actual_sql:
SELECT "patient_id", "sex", "birthday"
FROM "Patient"
WHERE "ldh" < 140 OR "ldh" > 280;

SELECT (COUNT(CASE WHEN "gender" = 'Female' THEN 1 END)::float / COUNT(*)) * 100 AS percentage
FROM "Patient"
WHERE "birth_year" = 1980 AND "diagnosis" = 'RA';

SELECT ROUND(100.0 * SUM(CASE WHEN "pt_status" = 'abnormal' THEN 1 ELSE 0 END) / NULLIF(COUNT(*), 0), 2) AS abnormal_pt_percentage
FROM "Patient"
WHERE "age" > 55 AND "gender" = 'Female';
